def round_half_to_even(n):
    if n.is_integer():
        return n
    elif n.is_number():
        if n - int(n) == 0.5:
            return int(n)
        elif n - int(n) < 0.5:
            return int(n)
        else:
            return int(n) + 1
    else:
        return n

