def xargs(
  cmd: tuple[str, ...],
  varargs: Sequence[str],
  *,
  color: bool = False,
  target_concurrency: int = 1,
  _max_length: int = _get_platform_max_length(),
  **kwargs: Any,
) -> tuple[int, bytes]:

  concurrency_var = 1
  while True:
    if concurrency_var < target_concurrency:
      concurrency_var *= 2
    else:
      break

  workers = [Worker(cmd, varargs, concurrency_var, kwargs) for _ in range(concurrency_var)]

  for worker in workers:
    worker.start()

  for worker in workers:
    worker.join()

  return (concurrency_var, b''.join(worker.stdout for worker in workers))

def xargs(cmd, varargs, color=False, target_concurrency=1, _max_length=_get_platform_max_length(), **kwargs):
    if color and _get_platform_supports_pty():
        pty = True
    else:
        pty = False

    def run_partition(partition):
        if pty:
            kwargs['pty'] = True
        command = [cmd[0], *partition, *varargs]
        result = subprocess.run(command, **kwargs)
        return result.returncode, result.stdout

    partitions = list(chunks(varargs, _max_length // target_concurrency))
    results = [run_partition(partition) for partition in partitions]
    return (sum(code for code, _ in results), b''.join(stdout for _, stdout in results))

