def extostr(e: Exception, max_level: int = 30, max_path_level: int = 5) -> str:
    trace = e.__traceback__
    max_level = min(max_level, len(trace))
    max_path_level = min(max_path_level, len(trace))
    exstr = [str(e)]
    for i in range(max_level):
        try:
            line = trace[i].line
            fname = trace[i].filename
            exstr.append(f"File \"{fname}\", line {line}, in {trace[i].name}")
        except Exception:
            pass
    for i in range(max_path_level):
        try:
            fname = trace[i].filename
            exstr.append(f"File \"{fname}\", in {trace[i].name}")
        except Exception:
            pass
    return "".join(exstr)

