def indented_representation(obj, indent=0, debug=False):
    # Return a pretty formatted representation of obj
    # indent: indentation level (0 for no indentation)
    # debug: whether to output debug information

    # If the object is a tree, return a nested representation with circular links displayed
    if isinstance(obj, Tree):
        return repr(obj)

    # If the object has a repr() method, return its pretty formatted representation
    if hasattr(obj, 'pretty'):
        return obj.pretty(indent, debug)

    # If the object is a dictionary, return a pretty formatted representation of its keys and values
    if isinstance(obj, dict):
        if obj:
            items = [(repr(key), repr(val)) for key, val in obj.items()]
            return f'{{{", ".join(f"{k}: {v}" for k, v in items)}}}\n'
        return "{{}}"

    # If the object is a list, return a pretty formatted representation of its elements
    if isinstance(obj, list):
        if obj:
            items = [repr(elem) for elem in obj]
            return f'[{", ".join(items)}]\n'
        return "[]"

    # If the object is a set, return a pretty formatted representation of its members
    if isinstance(obj, set):
        if obj:
            items = [repr(elem) for elem in obj]
            return f'{{{", ".join(items)}}}\n'
        return "{{}}"

    # If the object is a tuple, return a pretty formatted representation of its elements
    if isinstance(obj, tuple):
        if obj:
            items = [repr(elem) for elem in obj]
            return f'({", ".join(items)})\n'
        return "()"

    # Otherwise, return the object's repr()
    return repr(obj)

