def _split_windows(s):
    # Very simplistic Windows command-line splitting
    if not s:
        return []
    quotes, cmdline = [], []
    for c in s:
        if c == '"':
            if quotes and quotes[-1] == '"':
                quotes.pop()
            else:
                quotes.append(c)
            continue
        if not quotes:
            if c == ' ':
                if cmdline:
                    yield ''.join(cmdline)
                    cmdline.clear()
                continue
            if c == ';':
                if cmdline:
                    yield ''.join(cmdline)
                    cmdline.clear()
                continue
        cmdline.append(c)
    if cmdline:
        yield ''.join(cmdline)

