def subprocess_run_helper(func, *args, timeout, extra_env=None):
    cmd = [sys.executable, "-m", func.__module__] + list(args)
    p = subprocess.Popen(cmd, env=extra_env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    try:
        outs, errs = p.communicate(timeout=timeout)
        err = errs.decode("utf-8").strip()
        if err:
            raise RuntimeError(err)
        return outs.decode("utf-8").strip()
    except subprocess.TimeoutExpired:
        p.kill()
        outs, errs = p.communicate()
        err = errs.decode("utf-8").strip()
        raise TimeoutError(err) from None

