def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI."""
    if not os.path.isfile(playbook_path):
        raise ValueError("playbook path not found")
    if extra_vars is None:
        extra_vars = {}
    if ansible_args is None:
        ansible_args = {}
    ansible_args.update({
        # extra-vars should be passed down to Ansible
        "extra-vars": extra_vars,
        # Current workspace should be set as the ansible inventory
        "inventory": ir_workspace.inventory_path,
    })
    cmd_args = []
    for key, value in ansible_args.items():
        # Plumb down any ansible args
        cmd_args.extend(["--{}".format(key), value])
    # Add the playbook path
    cmd_args.append(playbook_path)
    # Add the infrared plugin command line
    if ir_plugin is not None:
        cmd_args.extend(["-m", "infrared", ir_plugin.name])
    # Add the ansible-playbook command
    cmd_args.insert(0, "ansible-playbook")
    # Add the verbosity flag
    if verbose is not None:
        cmd_args.extend(["-{}".format(verbose)])
    cmd = " ".join(cmd_args)
    return cmd

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    # Validate parameters
    if not isinstance(ir_workspace, InfraredWorkspace):
        raise ValueError("ir_workspace should be an InfraredWorkspace object")
    if not isinstance(ir_plugin, InfraredPlugin):
        raise ValueError("ir_plugin should be an InfraredPlugin object")
    if not isinstance(playbook_path, str):
        raise ValueError("playbook_path should be a string")
    if verbose is not None and not isinstance(verbose, int):
        raise ValueError("verbose should be an integer")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise ValueError("extra_vars should be a dict")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise ValueError("ansible_args should be a dict")

    # Generate the Ansible arguments
    ansible_args = dict(**ansible_args) if ansible_args else {}
    if verbose is not None:
        ansible_args["-" + "v" * verbose] = True
    if extra_vars is not None:
        ansible_args["extra-vars"] = extra_vars

    # Run the Ansible playbook
    args = list(ansible_args.items())
    Arg = collections.namedtuple("Arg", "value, dest")
    args = [Arg(value=v, dest=k) for k, v in args]
    playbook = ir_workspace.build_playbook(ir_plugin, playbook_path)
    result = playbook.execute(*args)

    # Raise an error if the playbook failed
    if result.ok:
        return result.result
    else:
        raise RuntimeError(result.error_message)

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict"""
    extra_vars = {"extravars": vars_dict}
    cli_args = [os.path.join(ir_plugin.config["ansible_dir"], "ansible-playbook")] + cli_args
    ansible_executable = configuration.conf.get("runtime", "ansible_executable", default="/bin/ansible-playbook")
    ansible_command = [ansible_executable] + cli_args + ["--extravars", extra_vars]

    process = subprocess.Popen(ansible_command, stdin=sys.stdin, stdout=sys.stdout, stderr=sys.stderr)

    ansible_module.wait(process, interval=0.1, error_margin=10)

    global_state.play_context = {}

    return process.returncode

