    if not path.startswith(root):
        raise ValueError(f"{path} does not start with {root}")
    return path[len(root):]

public static void strip_root(String[] path, String root) {
    if (path[0] != root) {
        throw new Exception("Unable to strip root from path: path does not begin with root");
    }
    String[] newPath = Arrays.copyOfRange(path, 1, path.length);
    return newPath;
}

public static string StripRoot(string path, string root)
{
    if (path.StartsWith(root))
    {
        return path.Substring(root.Length);
    }
    else
    {
        throw new ArgumentException("Root is not found at the beginning of the path.", "path");
    }
}

